import { createHash, createHmac, generateKeyPairSync, createSign, createVerify, randomBytes } from 'node:crypto';
import { promisify } from 'node:util';

// ── 1. SHA-256 hash ───────────────────────────────────────────
const sha256 = (data) => createHash('sha256').update(data).digest('hex');
console.log('SHA-256:', sha256('Hello, world!'));
console.log('Same?   ', sha256('Hello, world!') === sha256('Hello, world!')); // true
console.log('Differs?', sha256('Hello, world!') === sha256('Hello, World!')); // false (avalanche)

// ── 2. HMAC for API request signing ──────────────────────────
const hmacSecret = randomBytes(32);
function signRequest(method, path, body, secret) {
  const payload = `${method}\n${path}\n${body}`;
  return createHmac('sha256', secret).update(payload).digest('hex');
}
function verifyRequest(method, path, body, signature, secret) {
  const expected = signRequest(method, path, body, secret);
  // Constant-time comparison to prevent timing attacks
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(signature, 'hex');
  return a.length === b.length && require('node:crypto').timingSafeEqual(a, b);
}
const sig = signRequest('POST', '/transfer', '{"amount":100}', hmacSecret);
console.log('Valid signature:', verifyRequest('POST', '/transfer', '{"amount":100}', sig, hmacSecret));

// ── 3. Ed25519 digital signature ──────────────────────────────
const { privateKey, publicKey } = generateKeyPairSync('ed25519');

function signMessage(message, privKey) {
  const sign = createSign('SHA512');  // Ed25519 uses SHA-512 internally
  sign.update(message);
  return sign.sign(privKey).toString('hex');
}

function verifyMessage(message, signature, pubKey) {
  const verify = createVerify('SHA512');
  verify.update(message);
  return verify.verify(pubKey, Buffer.from(signature, 'hex'));
}

const message = 'Transfer $100 to Bob';
const signature = signMessage(message, privateKey);
console.log('Signature:', signature.slice(0, 40) + '...');
console.log('Valid:', verifyMessage(message, signature, publicKey));             // true
console.log('Tampered:', verifyMessage('Transfer $999 to Bob', signature, publicKey)); // false

