// ── Hash function comparison ──────────────────────────────────
//
// Algorithm  │ Output  │ Speed     │ Security   │ Use
// ───────────┼─────────┼───────────┼────────────┼──────────────────────
// MD5        │ 128-bit │ Very fast │ BROKEN     │ Legacy checksums only
// SHA-1      │ 160-bit │ Fast      │ BROKEN     │ Do not use for security
// SHA-256    │ 256-bit │ Fast      │ Secure     │ General purpose, TLS
// SHA-512    │ 512-bit │ Fast      │ Secure     │ General purpose
// SHA-3-256  │ 256-bit │ Moderate  │ Secure     │ Alternative to SHA-2
// bcrypt     │ 60 char │ Slow ✓    │ Good       │ Password hashing
// Argon2id   │ Variable│ Slow+Mem ✓│ Best       │ Password hashing (preferred)

// ── When to use which primitive ──────────────────────────────
const USE_CASES = {
  'File integrity check (no secret needed)': 'SHA-256',
  'Prove message not tampered + know shared key': 'HMAC-SHA256',
  'Sign data with private key (non-repudiation)': 'Ed25519 or ECDSA',
  'Store user passwords': 'Argon2id (or bcrypt if Argon2 unavailable)',
  'Derive keys from passwords': 'PBKDF2 or Argon2 (use high iteration count)',
  'JWT token (shared secret)': 'HS256 (HMAC-SHA256)',
  'JWT token (asymmetric / public verifiable)': 'RS256 (RSA) or ES256 (ECDSA)',
};

// ── Argon2id recommended parameters (OWASP 2023) ─────────────
const ARGON2_PARAMS = {
  type: 'argon2id',       // Hybrid: memory-hard + side-channel resistant
  memoryCost: 64 * 1024,  // 64 MiB minimum; 128 MiB if server allows
  timeCost: 3,            // 3 iterations
  parallelism: 4,         // 4 threads
  // Result: ~100-300ms per hash — slows brute-force by 10^9x vs plain SHA-256
};

